package monitoring.agent

import java.text.Normalizer
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import java.nio.file.{Files, Paths, StandardOpenOption}
import java.nio.charset.StandardCharsets

object CircuitState extends Enumeration {
  val Closed, Open, HalfOpen = Value
}

class CircuitBreaker(
  val failureThreshold: Int = 5,
  val resetTimeoutMs: Long = 30000
) {
  @volatile private var state: CircuitState.Value = CircuitState.Closed
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)

  def execute[T](operation: => T): Either[String, T] = {
    state match {
      case CircuitState.Open =>
        if (System.currentTimeMillis() - lastFailureTime.get() > resetTimeoutMs) {
          state = CircuitState.HalfOpen
          tryOperation(operation)
        } else {
          Left("Circuit breaker is OPEN")
        }
      case CircuitState.HalfOpen =>
        tryOperation(operation)
      case CircuitState.Closed =>
        tryOperation(operation)
    }
  }

  private def tryOperation[T](operation: => T): Either[String, T] = {
    try {
      val result = operation
      onSuccess()
      Right(result)
    } catch {
      case e: Exception =>
        onFailure()
        Left(e.getMessage)
    }
  }

  private def onSuccess(): Unit = {
    failureCount.set(0)
    state = CircuitState.Closed
  }

  private def onFailure(): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (count >= failureThreshold) {
      state = CircuitState.Open
    }
  }
}

trait LogSanitizer {
  def sanitize(input: String): String
}

class UnicodeAwareLogSanitizer extends LogSanitizer {
  private val dangerousPatterns = Set(
    "../", "..\\", "%2e%2e", "\r\n", "\n", "\r"
  )

  private val controlCharRegex = "[\\x00-\\x1f\\x7f]".r

  override def sanitize(input: String): String = {
    // First normalize to NFC to handle equivalent representations
    val normalized = Normalizer.normalize(input, Normalizer.Form.NFC)

    // Remove control characters
    val noControl = controlCharRegex.replaceAllIn(normalized, "")

    // Check for dangerous patterns
    val lower = noControl.toLowerCase
    val safe = dangerousPatterns.foldLeft(lower) { (acc, pattern) =>
      acc.replace(pattern, "[BLOCKED]")
    }
    safe
  }
}

class MetricIdentifierValidator {
  // Validates metric names - allows alphanumeric, dots, hyphens, underscores
  private val validMetricPattern = "^[a-zA-Z0-9._\\-]+$".r

  def validate(metricId: String): Boolean = {
    // Normalize to NFKC for consistent comparison
    val normalized = Normalizer.normalize(metricId, Normalizer.Form.NFKC)
    validMetricPattern.findFirstIn(normalized).isDefined
  }

  def normalizeIdentifier(metricId: String): String = {
    // Use NFC for storage normalization
    Normalizer.normalize(metricId, Normalizer.Form.NFC)
  }
}

class MonitoringAgent(
  logDir: String,
  sanitizer: LogSanitizer,
  validator: MetricIdentifierValidator
) {
  private val circuitBreaker = new CircuitBreaker()

  def recordMetric(metricId: String, value: Double, tags: Map[String, String]): Either[String, Unit] = {
    circuitBreaker.execute {
      // Validate the metric identifier using NFKC
      if (!validator.validate(metricId)) {
        throw new IllegalArgumentException(s"Invalid metric identifier")
      }

      // Normalize for storage using NFC (different form than validation!)
      val normalizedId = validator.normalizeIdentifier(metricId)

      val sanitizedTags = tags.map { case (k, v) =>
        (sanitizer.sanitize(k), sanitizer.sanitize(v))
      }

      val logEntry = formatLogEntry(normalizedId, value, sanitizedTags)
      writeToLog(normalizedId, logEntry)
    }
  }

  private def formatLogEntry(metricId: String, value: Double, tags: Map[String, String]): String = {
    val tagStr = tags.map { case (k, v) => s"$k=$v" }.mkString(",")
    s"[${System.currentTimeMillis()}] metric=$metricId value=$value tags={$tagStr}"
  }

  private def writeToLog(metricId: String, entry: String): Unit = {
    // Use metric ID as part of the log file path for partitioning
    val logFile = Paths.get(logDir, s"metrics_${metricId}.log")
    Files.write(
      logFile,
      (entry + "\n").getBytes(StandardCharsets.UTF_8),
      StandardOpenOption.CREATE,
      StandardOpenOption.APPEND
    )
  }
}

object MonitoringAgentApp {
  def main(args: Array[String]): Unit = {
    val sanitizer = new UnicodeAwareLogSanitizer()
    val validator = new MetricIdentifierValidator()
    val agent = new MonitoringAgent("/var/log/metrics", sanitizer, validator)

    // Example usage
    agent.recordMetric("cpu.usage", 85.5, Map("host" -> "server1", "region" -> "us-east"))
  }
}
